mapper.update:
UPDATE nw_knowledge_base_revisions
SET status = 'ready',
    source_versions = #{sourceVersions, typeHandler=com.skillforge.core.shared.config.JsonbTypeHandler},
    ready_at = now()
WHERE tenant_id = #{tenantId}
  AND kb_id = #{kbId}
  AND revision = #{revision}
  AND status = 'draft'

UPDATE nw_knowledge_base_revisions
SET status = 'archived'
WHERE tenant_id = #{tenantId}
  AND kb_id = #{kbId}
  AND status = 'published'
  AND id <> (
      SELECT id FROM nw_knowledge_base_revisions
      WHERE tenant_id = #{tenantId}
        AND kb_id = #{kbId}
        AND revision = #{revision}
  )

UPDATE nw_knowledge_base_revisions
SET status = 'published',
    published_at = now()
WHERE tenant_id = #{tenantId}
  AND kb_id = #{kbId}
  AND revision = #{revision}
  AND status = 'ready'

UPDATE nw_knowledge_bases
SET active_revision_id = #{revisionId},
    updated_at = now()
WHERE tenant_id = #{tenantId}
  AND id = #{kbId}
